def parse_line(line):
    """Parse a single log line of the form 'LEVEL ts msg'.

    Returns a dict with keys ``level``, ``ts`` and ``msg`` on success, where
    ``ts`` is converted to an int.  Returns ``None`` for malformed lines
    (missing fields, or a non-integer timestamp).
    """
    if not isinstance(line, str):
        return None

    parts = line.strip().split(maxsplit=2)
    if len(parts) < 3:
        return None

    level, ts_str, msg = parts
    try:
        ts = int(ts_str)
    except ValueError:
        return None

    return {"level": level, "ts": ts, "msg": msg}
